DECLARE @match_id int=?;
SELECT d.[match_id],d.[competition_id],d.[season_id],d.[match_date],d.[kick_off],d.[home_score],d.[away_score],d.[match_week],d.[competition_stage_id],d.[competition_stage_name],d.[stadium_id],d.[referee_id],d.[match_status],d.[match_status_360],d.[last_updated],d.[last_updated_360],d.[data_version],d.[shot_fidelity_version],d.[xy_fidelity_version] FROM analytics.[matches] d WHERE d.match_id=@match_id;
SELECT d.[match_id],d.[team_id],d.[side],d.[team_group] FROM analytics.[match_teams] d WHERE d.match_id=@match_id;
SELECT d.[match_id],d.[team_id],d.[player_id],d.[jersey_number],p.player_name,p.player_nickname FROM analytics.[match_lineups] d JOIN analytics.players p ON p.player_id=d.player_id WHERE d.match_id=@match_id;
SELECT d.[match_id],d.[team_id],d.[player_id],d.[position_index],d.[position_id],d.[position],d.[from_time],d.[to_time],d.[from_period],d.[to_period],d.[start_reason],d.[end_reason] FROM analytics.[lineup_positions] d WHERE d.match_id=@match_id;
SELECT d.[match_id],d.[team_id],d.[player_id],d.[card_index],d.[time],d.[card_type],d.[reason],d.[period] FROM analytics.[lineup_cards] d WHERE d.match_id=@match_id;
SELECT d.[event_id],d.[match_id],d.[event_index],d.[period],d.[timestamp],d.[minute],d.[second],d.[type_id],d.[type_name],d.[possession],d.[possession_team_id],d.[play_pattern_id],d.[play_pattern_name],d.[team_id],d.[player_id],d.[position_id],d.[position_name],d.[location_x],d.[location_y],d.[duration],d.[under_pressure],d.[counterpress],d.[off_camera],d.[out],d.[details],d.[period_time_ms] FROM analytics.[events] d WHERE d.match_id=@match_id ORDER BY d.event_index;
SELECT d.[event_id],d.[event_type_id],d.[team_id],d.[match_id],d.[recipient_player_id],d.[length],d.[angle],d.[height],d.[end_x],d.[end_y],d.[body_part],d.[pass_type],d.[outcome],d.[technique],d.[shot_assist],d.[goal_assist],d.[cross],d.[cut_back],d.[switch],d.[backheel],d.[deflected],d.[miscommunication],d.[aerial_won],d.[through_ball],d.[inswinging],d.[outswinging] FROM analytics.[event_passes] d WHERE d.match_id=@match_id;
SELECT d.[event_id],d.[event_type_id],d.[team_id],d.[match_id],d.[statsbomb_xg],d.[end_x],d.[end_y],d.[end_z],d.[key_pass_id],d.[shot_type],d.[outcome],d.[technique],d.[body_part],d.[aerial_won],d.[follows_dribble],d.[first_time],d.[open_goal],d.[deflected] FROM analytics.[event_shots] d WHERE d.match_id=@match_id;
SELECT d.[event_id],d.[match_id],d.[related_event_id] FROM analytics.[event_relations] d WHERE d.match_id=@match_id;
SELECT d.[event_id],d.[event_type_id],d.[team_id],d.[match_id],d.[formation] FROM analytics.[event_tactics] d WHERE d.match_id=@match_id;
SELECT d.[event_id],d.[team_id],d.[match_id],d.[player_id],d.[position_id],d.[position_name],d.[jersey_number] FROM analytics.[tactical_lineups] d WHERE d.match_id=@match_id;
SELECT d.[run_id],d.[match_id],d.[label],d.[seed],d.[generator_name],d.[generator_version],d.[config],d.[sample_rate_hz],d.[pitch_length_m],d.[pitch_width_m],d.[is_synthetic],d.[max_event_offset_ms] FROM analytics.[tracking_runs] d WHERE d.match_id=@match_id;
SELECT d.[run_id],d.[period],d.[match_id],d.[duration_ms],d.[home_attacks_positive_x] FROM analytics.[tracking_periods] d WHERE d.match_id=@match_id;
SELECT d.[event_id],d.[match_id],d.[visible_area] FROM analytics.[frames_360] d WHERE d.match_id=@match_id;
SELECT d.[event_id],d.[shot_team_id],d.[match_id],d.[frame_player_index],d.[player_id],d.[position_id],d.[position_name],d.[location_x],d.[location_y],d.[teammate] FROM analytics.[shot_freeze_players] d WHERE d.match_id=@match_id;
SELECT d.[event_id],d.[frame_player_index],d.[location_x],d.[location_y],d.[teammate],d.[actor],d.[keeper] FROM analytics.[frame_360_players] d WHERE d.event_id IN(SELECT event_id FROM analytics.events WHERE match_id=@match_id);
SELECT d.[event_id],d.[run_id],d.[match_id],d.[period],d.[frame_index],d.[alignment_method] FROM analytics.[event_tracking_links] d WHERE d.match_id=@match_id;
